-- V2.5 economy foundation — additive: SP ledger, lifetime caps, equipment, production cycles, XP.
-- Generated by hand to mirror the Prisma datamodel; extends Phase 6B.1 (which must be applied first).
-- ADDITIVE ONLY: new enums, new tables, new defaulted/nullable columns, indexes, FKs, constraints.
-- No existing column/row is removed or retyped. Apply ONLY after a verified backup and owner approval.
-- Recommended: apply inside a single transaction.

-- ---------------------------------------------------------------------------
-- CreateEnum
-- ---------------------------------------------------------------------------
CREATE TYPE "EquipmentTier" AS ENUM ('STANDARD', 'EXTENDED', 'ADVANCED');
CREATE TYPE "ProductionCycleStatus" AS ENUM ('PRODUCING', 'CLAIMED', 'CANCELLED');
CREATE TYPE "SpBucket" AS ENUM ('EARNED', 'BONUS');
CREATE TYPE "SpSourceType" AS ENUM (
  'CYCLE_CLAIM', 'MISSION_REWARD', 'REFERRAL_REWARD', 'SPECIAL_TASK_REWARD',
  'EQUIPMENT_PURCHASE', 'ADMIN_ADJUSTMENT',
  'WITHDRAWAL_LOCK', 'WITHDRAWAL_SETTLE', 'WITHDRAWAL_RELEASE'
);

-- ---------------------------------------------------------------------------
-- AlterTable: additive fields on existing tables
-- ---------------------------------------------------------------------------
ALTER TABLE "CEO"
  ADD COLUMN "nominalSpPer24h" INTEGER,
  ADD COLUMN "lifetimeCapSp"   BIGINT;

ALTER TABLE "OwnedCeo"
  ADD COLUMN "equipment"        "EquipmentTier" NOT NULL DEFAULT 'STANDARD',
  ADD COLUMN "lifetimeEarnedSp" BIGINT          NOT NULL DEFAULT 0,
  ADD COLUMN "archivedAt"       TIMESTAMP(3);

-- ---------------------------------------------------------------------------
-- CreateTable
-- ---------------------------------------------------------------------------
CREATE TABLE "ProductionCycle" (
    "id"                  BIGSERIAL    NOT NULL,
    "userId"              INTEGER      NOT NULL,
    "ownedCeoId"          INTEGER      NOT NULL,
    "status"              "ProductionCycleStatus" NOT NULL DEFAULT 'PRODUCING',
    "startsAt"            TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "endsAt"              TIMESTAMP(3) NOT NULL,
    "nominalSpPer24hSnap" INTEGER      NOT NULL,
    "equipmentSnap"       "EquipmentTier" NOT NULL,
    "cycleHoursSnap"      INTEGER      NOT NULL,
    "rewardSpSnap"        BIGINT       NOT NULL,
    "lifetimeCapSnap"     BIGINT       NOT NULL,
    "claimedAt"           TIMESTAMP(3),
    "cancelledAt"         TIMESTAMP(3),
    "createdAt"           TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"           TIMESTAMP(3) NOT NULL,
    CONSTRAINT "ProductionCycle_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "SpAccount" (
    "userId"           INTEGER      NOT NULL,
    "earnedSp"         BIGINT       NOT NULL DEFAULT 0,
    "bonusSp"          BIGINT       NOT NULL DEFAULT 0,
    "lifetimeEarnedSp" BIGINT       NOT NULL DEFAULT 0,
    "version"          INTEGER      NOT NULL DEFAULT 0,
    "updatedAt"        TIMESTAMP(3) NOT NULL,
    CONSTRAINT "SpAccount_pkey" PRIMARY KEY ("userId")
);

CREATE TABLE "SpLedgerEntry" (
    "id"                   BIGSERIAL   NOT NULL,
    "userId"               INTEGER     NOT NULL,
    "bucket"               "SpBucket"  NOT NULL,
    "amountSp"             BIGINT      NOT NULL,
    "balanceAfterEarnedSp" BIGINT      NOT NULL,
    "balanceAfterBonusSp"  BIGINT      NOT NULL,
    "sourceType"           "SpSourceType" NOT NULL,
    "sourceId"             BIGINT,
    "metadata"             JSONB,
    "createdAt"            TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "SpLedgerEntry_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ProgressAccount" (
    "userId"    INTEGER      NOT NULL,
    "xp"        INTEGER      NOT NULL DEFAULT 0,
    "level"     INTEGER      NOT NULL DEFAULT 1,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "ProgressAccount_pkey" PRIMARY KEY ("userId")
);

-- ---------------------------------------------------------------------------
-- CreateIndex
-- ---------------------------------------------------------------------------
CREATE INDEX "ProductionCycle_userId_status_idx" ON "ProductionCycle"("userId", "status");
CREATE INDEX "ProductionCycle_ownedCeoId_idx"    ON "ProductionCycle"("ownedCeoId");
CREATE INDEX "ProductionCycle_status_endsAt_idx" ON "ProductionCycle"("status", "endsAt");

CREATE INDEX "SpLedgerEntry_userId_createdAt_idx" ON "SpLedgerEntry"("userId", "createdAt");

-- Exactly-once SP credit per source event and bucket.
CREATE UNIQUE INDEX "SpLedgerEntry_userId_sourceType_sourceId_bucket_key"
  ON "SpLedgerEntry"("userId", "sourceType", "sourceId", "bucket");

-- One open (PRODUCING) cycle per owned copy (concurrency backstop for start).
CREATE UNIQUE INDEX "ProductionCycle_open_owned_key"
  ON "ProductionCycle"("ownedCeoId")
  WHERE "status" = 'PRODUCING';

-- ---------------------------------------------------------------------------
-- AddForeignKey
-- ---------------------------------------------------------------------------
ALTER TABLE "ProductionCycle" ADD CONSTRAINT "ProductionCycle_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProductionCycle" ADD CONSTRAINT "ProductionCycle_ownedCeoId_fkey"
  FOREIGN KEY ("ownedCeoId") REFERENCES "OwnedCeo"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "SpAccount" ADD CONSTRAINT "SpAccount_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "SpLedgerEntry" ADD CONSTRAINT "SpLedgerEntry_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ProgressAccount" ADD CONSTRAINT "ProgressAccount_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ===========================================================================
-- CATALOG SEED — OWNER-APPROVED (2026-10-18)
-- ===========================================================================
-- The owner approved eight tiers with the prices / nominal SP-per-24h / lifetime caps
-- in Master Spec §3, and approved mapping the seven premium tiers (CEO 2–8) onto the
-- existing premium slugs in ascending price order, retiring the surplus row.
-- Existing ids and collection identities are preserved; only economy fields change.
-- The surplus row (`crypto-whale`) is set inactive, never deleted, so historical
-- ownership/transactions remain valid. Catalog reads should request active rows only.
--
-- Mapping (slug -> tier): junior-developer=CEO2, product-manager=CEO3, marketing-director=CEO4,
-- startup-founder=CEO5, ai-architect=CEO6, cloud-executive=CEO7, tech-billionaire=CEO8;
-- crypto-whale surplus -> inactive.

UPDATE "CEO" SET "priceUsd" = 0.00,   "nominalSpPer24h" = 10,      "lifetimeCapSp" = 40,       "isActive" = true  WHERE "slug" = 'intern-ceo';
UPDATE "CEO" SET "priceUsd" = 0.99,   "nominalSpPer24h" = 100,     "lifetimeCapSp" = 1200,     "isActive" = true  WHERE "slug" = 'junior-developer';
UPDATE "CEO" SET "priceUsd" = 4.99,   "nominalSpPer24h" = 1000,    "lifetimeCapSp" = 6500,     "isActive" = true  WHERE "slug" = 'product-manager';
UPDATE "CEO" SET "priceUsd" = 19.99,  "nominalSpPer24h" = 5000,    "lifetimeCapSp" = 28000,    "isActive" = true  WHERE "slug" = 'marketing-director';
UPDATE "CEO" SET "priceUsd" = 49.99,  "nominalSpPer24h" = 10000,   "lifetimeCapSp" = 75000,    "isActive" = true  WHERE "slug" = 'startup-founder';
UPDATE "CEO" SET "priceUsd" = 99.99,  "nominalSpPer24h" = 25000,   "lifetimeCapSp" = 160000,   "isActive" = true  WHERE "slug" = 'ai-architect';
UPDATE "CEO" SET "priceUsd" = 249.99, "nominalSpPer24h" = 50000,   "lifetimeCapSp" = 450000,   "isActive" = true  WHERE "slug" = 'cloud-executive';
UPDATE "CEO" SET "priceUsd" = 999.99, "nominalSpPer24h" = 100000,  "lifetimeCapSp" = 2000000,  "isActive" = true  WHERE "slug" = 'tech-billionaire';
UPDATE "CEO" SET "isActive" = false WHERE "slug" = 'crypto-whale';
-- Test artifact row (not an approved tier): hide from the catalog, keep for history.
UPDATE "CEO" SET "isActive" = false WHERE "slug" = 'test-ceo';
